rules:
// VAV controller check (main control / supply / exhaust layout).
// p = current reading, prev = previous one. Duct sizes are in METRES.
// An unused duct is left at size 0 and contributes nothing to the total.
const has=k=>typeof p[k]==='number'&&isFinite(p[k]);
const near=(a,b,pct,abs)=>Math.abs(a-b)<=Math.abs(a)*pct/100+(abs||1);

// Ducts on one side. Handles both the per-duct shape (Supply1/Supply2)
// and the older single-pair shape (Supply).
function ducts(side, src){
  const list=[];
  for(const i of ['1','2','']){
    const H=side+i+'H', V=side+i+'V', v='Speed'+side+i, k='K'+side+i;
    if(has(H)&&has(V)&&has(v)&&p[H]*p[V]>0)
      list.push({area:p[H]*p[V], speed:(src||p)[v], coeff:has(k)?p[k]:1});
  }
  return list;
}
const flowOf=list=>list.reduce((sum,d)=>sum+d.coeff*d.speed*d.area*3600,0);
const supply=ducts('Supply'), exhaust=ducts('Return');

// Correct flow: sum of speed x own cross-section, per duct.
const supplyCalc=flowOf(supply), exhaustCalc=flowOf(exhaust);
// Flow as reported by the device; without that point fall back to the computed one.
const supplyFlow=has('FlowSupply')?p.FlowSupply:supplyCalc;
const exhaustFlow=has('FlowReturn')?p.FlowReturn:exhaustCalc;

// CO2 ramp and operating mode
const rampStart=p.CO2Setpoint-p.CO2PropBand;
const ramp=Math.min(1,Math.max(0,(p.CO2-rampStart)/(p.CO2PropBand||1)));
const autoSetpoint=p.MinFlow+ramp*(p.MaxFlow-p.MinFlow);
const mode=Number(p.Mode);
const supplySp=mode===1?autoSetpoint:mode===2?p.MinFlow:mode===3?p.MaxFlow:0;
const exhaustSp=supplySp-p.Diff;

// Judge the control loop only once it has settled. The previous flow is derived
// the same way as the current one; otherwise, with FlowSupply missing, we would
// compare a value with itself and every transient would look settled.
const steady=(a,b)=>near(a,b,1,5);
const supplyPrev=has('FlowSupply')?prev.FlowSupply:flowOf(ducts('Supply',prev));
const exhaustPrev=has('FlowReturn')?prev.FlowReturn:flowOf(ducts('Return',prev));
const settled=steady(supplyFlow,supplyPrev)&&steady(exhaustFlow,exhaustPrev);
const atLimit=pos=>has('PositionSupply')?(pos>=99||pos<=1):false;
const skip=pos=>!settled||atLimit(pos);

const rows=[];
if(has('FlowSupply')&&supply.length)
  rows.push(['przeplyw nawiewu = suma (predkosc x przekroj kanalu) x 3600',
    supplyCalc, p.FlowSupply, near(supplyCalc,p.FlowSupply,3)]);
if(has('FlowReturn')&&exhaust.length)
  rows.push(['przeplyw wyciagu = suma (predkosc x przekroj kanalu) x 3600',
    exhaustCalc, p.FlowReturn, near(exhaustCalc,p.FlowReturn,3)]);
rows.push(['nastawa nawiewu wg rampy CO2 i trybu', supplySp, supplyFlow,
  skip(p.PositionSupply)||near(supplySp,supplyFlow,10,20)]);
rows.push(['wyciag nadaza za nawiewem (nawiew - DIFF)', exhaustSp, exhaustFlow,
  skip(p.PositionReturn)||near(exhaustSp,exhaustFlow,10,20)]);
rows.push(['roznica nawiew-wyciag = DIFF', p.Diff, supplyFlow-exhaustFlow,
  skip(p.PositionSupply)||skip(p.PositionReturn)||near(p.Diff,supplyFlow-exhaustFlow,10,25)]);

// Catches the older implementation: speeds summed, then multiplied by ONE
// cross-section. That reports a false flow wherever the two ducts differ.
function checkSingleAreaSumming(list, reported, label){
  if(list.length<2||!isFinite(reported)) return;
  const speedSum=list.reduce((sum,d)=>sum+d.coeff*d.speed,0);
  const correct=flowOf(list);
  for(const d of list){
    const wrong=speedSum*d.area*3600;
    if(near(wrong,reported,3)&&!near(correct,reported,3))
      rows.push([label, correct, reported, false]);
  }
}
checkSingleAreaSumming(supply, p.FlowSupply, 'BLAD: nawiew sumuje predkosci i mnozy przez JEDEN przekroj');
checkSingleAreaSumming(exhaust, p.FlowReturn, 'BLAD: wyciag sumuje predkosci i mnozy przez JEDEN przekroj');

// Report missing points explicitly so they cannot masquerade as a control fault.
const required=['Mode','MinFlow','MaxFlow','CO2PropBand','CO2Setpoint','Diff','CO2'];
const missing=required.filter(k=>!has(k));
if(missing.length)
  rows.push(['BRAK PUNKTOW (sprawdz mapowanie): '+missing.join(', '), 0, missing.length, false]);
if(!supply.length) rows.push(['BRAK kanalu nawiewnego (wymiary + predkosc)', 1, 0, false]);
if(!exhaust.length) rows.push(['BRAK kanalu wyciagowego (wymiary + predkosc)', 1, 0, false]);

// Configuration sanity checks
if([...supply,...exhaust].some(d=>d.area>10))
  rows.push(['wymiary kanalu w METRACH (wpisano mm?)', 1, 0, false]);
if(p.MinFlow>=p.MaxFlow) rows.push(['MinFlow < MaxFlow', 1, 0, false]);
if(p.CO2PropBand<=0) rows.push(['PropBand > 0', 1, 0, false]);
if(mode===4) rows.push(['UWAGA: tryb OFF (4) - regulacja wylaczona', 1, 0, false]);
return rows;
